"""Bounded pilot: incremental NP/Z patching and separate retrospective probes."""

from __future__ import annotations

import hashlib
import importlib.metadata
import json
import platform
import time
from collections import defaultdict
from pathlib import Path

import numpy as np
import torch

from v2.materials import garden_paths, role_items


def family_interval(values: list[tuple[str, float]]) -> dict:
    groups = defaultdict(list)
    for family, value in values:
        if not np.isfinite(value):
            raise ValueError("Nonfinite measurement")
        groups[family].append(value)
    means = np.array([np.mean(x) for x in groups.values()])
    if not len(means):
        raise ValueError("No observations")
    draws = np.random.default_rng(0).choice(means, (10000, len(means))).mean(axis=1)
    return {
        "mean": float(means.mean()),
        "ci95": np.quantile(draws, [0.025, 0.975]).tolist(),
        "families": len(means),
    }


def token_position(offsets: list, start: int, end: int) -> int:
    hits = [i for i, (a, b) in enumerate(offsets) if b > start and a < end]
    if not hits or offsets[hits[-1]][1] != end or offsets[hits[0]][0] > start:
        raise ValueError("Token offsets do not cover the requested span exactly")
    return hits[-1]


def patch_state(output, position: int, donor: torch.Tensor):
    state = output[0] if isinstance(output, tuple) else output
    changed = state.clone()
    changed[:, position, :] = donor.to(device=state.device, dtype=state.dtype)
    return (changed, *output[1:]) if isinstance(output, tuple) else changed


def ridge_predict(train: np.ndarray, labels: np.ndarray, test: np.ndarray) -> np.ndarray:
    """Fixed ridge penalty; training-only centering/scaling, dual solution."""
    center = train.mean(axis=0)
    train, test = train - center, test - center
    scale = max(float(np.sqrt(np.mean(train**2))), 1e-12)
    train, test = train / scale, test / scale
    y = 2 * labels.astype(float) - 1
    bias = y.mean()
    kernel = train @ train.T / train.shape[1]
    weights = np.linalg.solve(kernel + np.eye(len(train)), y - bias)
    return test @ train.T / train.shape[1] @ weights + bias


class Measurements:
    def __init__(self, model, tokenizer):
        self.model, self.tokenizer = model, tokenizer
        self.layers = model.model.layers
        self.device = next(model.parameters()).device

    def encode(self, text: str) -> dict:
        data = self.tokenizer(text, return_tensors="pt", return_offsets_mapping=True)
        offsets = data.pop("offset_mapping")[0].tolist()
        return {"inputs": {k: v.to(self.device) for k, v in data.items()}, "offsets": offsets}

    def capture(self, prefix: str, continuation: str = "") -> tuple[list[torch.Tensor], int]:
        data = self.encode(prefix)
        position = token_position(data["offsets"], prefix.rfind(" ") + 1, len(prefix))
        if continuation:
            full = self.encode(prefix + " " + continuation)
            ids = data["inputs"]["input_ids"]
            if not torch.equal(full["inputs"]["input_ids"][:, : ids.shape[1]], ids):
                raise ValueError("Continuation changes prefix tokenization")
            # Match scoring GEMM shapes in BF16. The causal mask prevents the
            # recorded prefix position from seeing these teacher-forced tokens.
            data = full
        captured = []

        def hook(_module, _inputs, output):
            state = output[0] if isinstance(output, tuple) else output
            captured.append(state[0, position].detach().float().cpu())

        handles = [layer.register_forward_hook(hook) for layer in self.layers]
        try:
            with torch.inference_mode():
                self.model(**data["inputs"], use_cache=False)
        finally:
            for handle in handles:
                handle.remove()
        return captured, position

    def score(self, prefix: str, word: str, patch: tuple | None = None) -> float:
        base = self.encode(prefix)["inputs"]["input_ids"][0]
        data = self.encode(prefix + " " + word)
        ids = data["inputs"]["input_ids"][0]
        if not torch.equal(ids[: len(base)], base) or len(ids) <= len(base):
            raise ValueError("Continuation changes prefix tokenization")
        handle = None
        if patch is not None:
            layer, position, donor = patch
            handle = self.layers[layer].register_forward_hook(
                lambda _m, _i, output: patch_state(output, position, donor)
            )
        try:
            with torch.inference_mode():
                logits = self.model(**data["inputs"], use_cache=False).logits[0].float()
                indices = torch.arange(len(base), len(ids), device=self.device)
                value = (
                    logits[indices - 1].log_softmax(-1).gather(1, ids[indices, None]).sum().item()
                )
        finally:
            if handle is not None:
                handle.remove()
        if not np.isfinite(value):
            raise ValueError("Nonfinite log probability")
        return value


def run_garden_paths(measure: Measurements) -> dict:
    rows = []
    for item in garden_paths():
        for site in ("pre_disambiguation", "post_disambiguation"):
            suffix = "" if site == "pre_disambiguation" else " " + item["critical"]
            word = item["critical"] if not suffix else item["spillover"]
            prefixes = {
                c: item[c] + suffix
                for c in ("clean", "ambiguous", "lexical_clean", "lexical_ambiguous")
            }
            states = {c: measure.capture(p, continuation=word) for c, p in prefixes.items()}
            baseline = {c: measure.score(prefixes[c], word) for c in ("clean", "ambiguous")}
            for recipient, donor in (("ambiguous", "clean"), ("clean", "ambiguous")):
                for layer in range(len(measure.layers)):
                    target_states, pos = states[recipient]
                    value = measure.score(
                        prefixes[recipient], word, (layer, pos, states[donor][0][layer])
                    )
                    lexical = states["lexical_" + recipient][0][layer]
                    control = measure.score(prefixes[recipient], word, (layer, pos, lexical))
                    self_score = measure.score(
                        prefixes[recipient], word, (layer, pos, target_states[layer])
                    )
                    if abs(self_score - baseline[recipient]) > 1e-4:
                        raise ValueError(
                            f"Self patch failed: {item['id']} {site} {recipient} L{layer}: {self_score - baseline[recipient]:.8g}"
                        )
                    rows.append(
                        {
                            "family": item["family"],
                            "site": site,
                            "layer": layer,
                            "recipient": recipient,
                            "donor": donor,
                            "word": word,
                            "prefix": prefixes[recipient],
                            "position": pos,
                            "baseline": baseline[recipient],
                            "donor_baseline": baseline[donor],
                            "patched": value,
                            "lexical_control": control,
                            "self_patch": self_score,
                            "effect": value - baseline[recipient],
                            "lexical_effect": control - baseline[recipient],
                            "patch_l2": float(
                                torch.linalg.vector_norm(
                                    states[donor][0][layer] - target_states[layer]
                                )
                            ),
                            "lexical_l2": float(
                                torch.linalg.vector_norm(lexical - target_states[layer])
                            ),
                        }
                    )
        print(f"Completed NP/Z family {item['family']}", flush=True)
    summaries = []
    for site in ("pre_disambiguation", "post_disambiguation"):
        for recipient in ("clean", "ambiguous"):
            for layer in range(len(measure.layers)):
                subset = [
                    r
                    for r in rows
                    if (r["site"], r["recipient"], r["layer"]) == (site, recipient, layer)
                ]
                summaries.append(
                    {
                        "site": site,
                        "recipient": recipient,
                        "layer": layer,
                        **{
                            name: family_interval([(r["family"], r[name]) for r in subset])
                            for name in ("effect", "lexical_effect")
                        },
                    }
                )
    return {"materials": garden_paths(), "rows": rows, "summaries": summaries}


def run_roles(measure: Measurements, out: Path) -> dict:
    items = role_items()
    features = np.stack(
        [np.stack([x.numpy() for x in measure.capture(r["prompt"])[0]]) for r in items]
    )
    np.savez_compressed(out / "role-activations.npz", features=features)
    train = np.array([i for i, r in enumerate(items) if r["split"] == "train"])
    results = []
    for target in ("subject", "agent"):
        labels = np.array([r[target] for r in items])
        shuffled = np.random.default_rng(0).permutation(labels[train])
        for layer in range(features.shape[1]):
            for domain in ("canonical", "fronted"):
                test = np.array(
                    [
                        i
                        for i, r in enumerate(items)
                        if r["split"] == "test"
                        and (r["construction"] in ("active", "passive")) == (domain == "canonical")
                    ]
                )
                scores = ridge_predict(features[train, layer], labels[train], features[test, layer])
                null = ridge_predict(features[train, layer], shuffled, features[test, layer])
                correct = (scores > 0) == labels[test]
                rows = [
                    {
                        "id": items[i]["id"],
                        "family": items[i]["family"],
                        "label": int(labels[i]),
                        "score": float(score),
                        "correct": bool(ok),
                        "shuffled_score": float(ns),
                    }
                    for i, score, ok, ns in zip(test, scores, correct, null, strict=True)
                ]
                results.append(
                    {
                        "target": target,
                        "layer": layer,
                        "domain": domain,
                        "accuracy": family_interval(
                            [(r["family"], float(r["correct"])) for r in rows]
                        ),
                        "shuffled_accuracy": float(np.mean((null > 0) == labels[test])),
                        "first_mention_accuracy": float(
                            np.mean([items[i]["first_mention"] == labels[i] for i in test])
                        ),
                        "rows": rows,
                    }
                )
    return {
        "materials": items,
        "results": results,
        "readout": "post-block state at the last token of a target cue after the complete sentence",
    }


def run(output: str, revision: str) -> None:
    from transformers import AutoModelForCausalLM, AutoTokenizer

    if len(revision) != 40 or any(c not in "0123456789abcdef" for c in revision):
        raise ValueError("An exact checkpoint SHA is required")
    out = Path(output)
    out.mkdir(parents=True, exist_ok=False)
    start = time.time()
    torch.manual_seed(0)
    np.random.seed(0)
    model_id = "google/gemma-3-1b-pt"
    source = Path(__file__).parent
    metadata = {
        "model": model_id,
        "revision": revision,
        "seed": 0,
        "dtype": "bfloat16",
        "attention": "eager",
        "layer_index": "zero-based, post-block",
        "versions": {
            name: importlib.metadata.version(name)
            for name in ("torch", "transformers", "numpy", "huggingface_hub")
        },
        "python": platform.python_version(),
        "gpu": torch.cuda.get_device_name(),
        "started_at_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "source_sha256": {
            p.name: hashlib.sha256(p.read_bytes()).hexdigest() for p in source.glob("*.py")
        },
        "materials_sha256": hashlib.sha256(
            json.dumps([garden_paths(), role_items()], sort_keys=True).encode()
        ).hexdigest(),
    }
    (out / "metadata.json").write_text(json.dumps(metadata, indent=2))
    (out / "source.json").write_text(
        json.dumps({p.name: p.read_text() for p in source.glob("*.py")}, indent=2)
    )
    tokenizer = AutoTokenizer.from_pretrained(model_id, revision=revision)
    model = (
        AutoModelForCausalLM.from_pretrained(
            model_id, revision=revision, dtype=torch.bfloat16, attn_implementation="eager"
        )
        .to("cuda")
        .eval()
    )
    measure = Measurements(model, tokenizer)
    for name, result in (("roles", run_roles(measure, out)),):
        (out / f"{name}.json").write_text(json.dumps(result, indent=2, allow_nan=False))
    result = run_garden_paths(measure)
    (out / "garden-paths.json").write_text(json.dumps(result, indent=2, allow_nan=False))
    metadata["elapsed_seconds"] = time.time() - start
    metadata["complete"] = True
    (out / "metadata.json").write_text(json.dumps(metadata, indent=2))

followup_modal.py:
"""Bounded independent Gemma 3 follow-ups; only allowlisted source/data are uploaded."""

from pathlib import Path

import modal

from v2.followup_run import SOURCE_FILES

ROOT = Path(__file__).resolve().parent
app = modal.App("garden-path-v2-followup")
cache = modal.Volume.from_name("gps-hf-cache", create_if_missing=True)
results = modal.Volume.from_name("gps-v2-results", create_if_missing=True)
image = (
    modal.Image.debian_slim(python_version="3.11")
    .pip_install("torch==2.10.0", "transformers==5.9.0", "numpy==2.4.3", "sentencepiece==0.2.1")
    .env(
        {
            "HF_HOME": "/cache/hf",
            "PYTHONPATH": "/app",
            "OMP_NUM_THREADS": "2",
            "OPENBLAS_NUM_THREADS": "2",
        }
    )
)
for name in SOURCE_FILES:
    image = image.add_local_file(ROOT / name, f"/app/v2/{name}")
for path in sorted((ROOT / "materials").glob("ud-*")):
    if path.is_file():
        image = image.add_local_file(path, f"/app/v2/materials/{path.name}")


@app.function(
    image=image,
    gpu="A10G",
    cpu=2,
    timeout=1200,
    retries=0,
    max_containers=1,
    volumes={"/cache/hf": cache, "/results": results},
    secrets=[modal.Secret.from_name("huggingface")],
)
def execute(run_id: str, track: str) -> dict[str, bytes]:
    from v2.followup_run import run_followup

    destination = Path("/results") / run_id
    try:
        run_followup(destination, track)
    finally:
        cache.commit()
        results.commit()
    return {p.name: p.read_bytes() for p in destination.iterdir() if p.is_file()}


@app.function(image=image, volumes={"/results": results}, timeout=120)
def collect(run_id: str) -> dict[str, bytes]:
    return {p.name: p.read_bytes() for p in (Path("/results") / run_id).iterdir() if p.is_file()}


@app.local_entrypoint()
def main(track: str = "garden", run_id: str = "", fetch: bool = False) -> None:
    import datetime
    import re

    if track not in ("garden", "roles"):
        raise ValueError("track must be garden or roles")
    run_id = run_id or f"{track}-" + datetime.datetime.now(datetime.UTC).strftime("%Y%m%dT%H%M%SZ")
    if not re.fullmatch(r"[a-zA-Z0-9_-]+", run_id):
        raise ValueError("Unsafe run ID")
    files = collect.remote(run_id) if fetch else execute.remote(run_id, track)
    destination = ROOT / "results" / run_id
    destination.mkdir(parents=True, exist_ok=True)
    for name, content in files.items():
        path = destination / name
        if path.exists() and path.read_bytes() != content:
            raise FileExistsError(f"Refusing to replace different result {path}")
        path.write_bytes(content)
    print(f"Saved {len(files)} files to {destination}")

garden_followup.py:
"""Exploratory NP/Z factorial assay with development-only layer selection."""

from __future__ import annotations

import hashlib
import json
from collections import defaultdict
from pathlib import Path

import numpy as np
import torch

from v2.experiment import family_interval


def garden_materials() -> list[dict]:
    """Synthetic sentences, frozen before inference; no human validation."""
    families = [
        ("painted", "sneezed", "artist", "painter", "colorful canvas"),
        ("knitted", "snored", "tailor", "weaver", "woolen scarf"),
        ("embroidered", "sighed", "designer", "dressmaker", "linen napkin"),
        ("baked", "dozed", "baker", "cook", "birthday cake"),
        ("studied", "fainted", "student", "scholar", "thick textbook"),
        ("sewed", "blushed", "seamstress", "costumer", "silk dress"),
        ("cleaned", "yawned", "caretaker", "janitor", "kitchen window"),
        ("wrote", "hesitated", "poet", "novelist", "short note"),
        ("drew", "stumbled", "illustrator", "cartoonist", "paper portrait"),
        ("cooked", "slept", "chef", "caterer", "vegetable stew"),
        ("ironed", "shivered", "butler", "housekeeper", "cotton shirt"),
        ("ate", "dined", "traveler", "tourist", "buttered toast"),
    ]
    rows = []
    for index, (verb, control, actor, other, target) in enumerate(families):
        prefixes, lexical = {}, {}
        for verb_class, word in (("optional_transitive", verb), ("intransitive", control)):
            prefixes[verb_class], lexical[verb_class] = {}, {}
            for condition, punctuation in (("comma", ","), ("no_comma", "")):
                for output, person in ((prefixes, actor), (lexical, other)):
                    output[verb_class][condition] = (
                        f"While the {person} {word}{punctuation} the {target}"
                    )
        rows.append(
            {
                "id": f"npz-followup-{index:02d}",
                "family": verb,
                "split": "development" if index < 6 else "test",
                "actor": actor,
                "other_actor": other,
                "control_verb": control,
                "target": target,
                "prefixes": prefixes,
                "lexical_prefixes": lexical,
                "continuations": {
                    "main": "was beside the table.",
                    "object": "beside the table, the assistant waited.",
                },
            }
        )
    return rows


def factorial_interaction(values: dict) -> float:
    """Comma effect in optional-transitive minus intransitive contexts."""
    return float(
        values["optional_transitive"]["comma"]
        - values["optional_transitive"]["no_comma"]
        - values["intransitive"]["comma"]
        + values["intransitive"]["no_comma"]
    )


def matched_state(
    target: torch.Tensor, direction: torch.Tensor, requested_l2: float, dtype: torch.dtype
) -> tuple[torch.Tensor, dict]:
    """Match in FP32, then report the displacement actually injected after casting."""
    norm = float(torch.linalg.vector_norm(direction.float()))
    if not np.isfinite(requested_l2) or requested_l2 < 0 or not np.isfinite(norm):
        raise ValueError("Nonfinite or negative patch norm")
    if norm == 0 and requested_l2 > 0:
        raise ValueError("Cannot norm-match a zero control direction")
    scale = requested_l2 / norm if norm else 0.0
    rounded = (target.float() + direction.float() * scale).to(dtype).float()
    return rounded, {
        "requested_l2": requested_l2,
        "actual_l2": float(torch.linalg.vector_norm(rounded - target.to(dtype).float())),
        "direction_l2": norm,
        "scale": scale,
    }


def select_layer(rows: list[dict], num_layers: int) -> int:
    """Choose the largest signed mean interaction; deterministic lower-layer tie break."""
    grouped = defaultdict(list)
    for row in rows:
        if row["split"] != "development" or not 0 <= row["layer"] < num_layers - 1:
            raise ValueError("Selection accepts development observations at non-final blocks only")
        if not np.isfinite(row["value"]):
            raise ValueError("Nonfinite selection observation")
        grouped[row["layer"]].append(row["value"])
    if not grouped:
        raise ValueError("No development observations")
    return max(sorted(grouped), key=lambda layer: float(np.mean(grouped[layer])))


def _intervention_interactions(rows: list[dict]) -> list[dict]:
    groups = defaultdict(dict)
    for row in rows:
        key = (row["split"], row["family"], row["layer"], row["kind"], row["random_seed"])
        groups[key][(row["verb_class"], row["recipient"], row["candidate"])] = row["effect"]
    result = []
    for (split, family, layer, kind, seed), values in groups.items():
        directions = {}
        for recipient, sign in (("no_comma", 1), ("comma", -1)):
            effects = {}
            for verb_class in ("optional_transitive", "intransitive"):
                effects[verb_class] = sign * (
                    values[(verb_class, recipient, "main")]
                    - values[(verb_class, recipient, "object")]
                )
            directions[recipient] = effects["optional_transitive"] - effects["intransitive"]
        result.append(
            {
                "split": split,
                "family": family,
                "layer": layer,
                "kind": kind,
                "random_seed": seed,
                "to_no_comma": directions["no_comma"],
                "to_comma": directions["comma"],
                "value": float(np.mean(list(directions.values()))),
            }
        )
    return result


def run_garden_followup(measure, out: Path) -> dict:
    """Run a bounded assay; retain raw scores, fixed-test selection and numerical checks."""
    items = garden_materials()
    num_layers = len(measure.layers)
    if num_layers < 2:
        raise ValueError("At least two blocks are required to exclude the readout block")
    dtype = next(measure.model.parameters()).dtype
    baselines, interventions, prepared = [], [], {}
    out.mkdir(parents=True, exist_ok=True)
    raw = (out / "garden-followup-observations.jsonl").open("x")

    def record(row):
        raw.write(json.dumps(row, allow_nan=False) + "\n")
        raw.flush()

    def prepare(item):
        cache = {}
        for verb_class, conditions in item["prefixes"].items():
            for condition, prefix in conditions.items():
                for candidate, completion in item["continuations"].items():
                    states, pos = measure.capture(prefix, continuation=completion)
                    lexical_prefix = item["lexical_prefixes"][verb_class][condition]
                    lexical, _ = measure.capture(lexical_prefix, continuation=completion)
                    score = measure.score(prefix, completion)
                    critical_score = measure.score(prefix, "was") if candidate == "main" else None
                    count = (
                        measure.encode(prefix + " " + completion)["inputs"]["input_ids"].shape[1]
                        - measure.encode(prefix)["inputs"]["input_ids"].shape[1]
                    )
                    row = {
                        "record": "baseline",
                        "family": item["family"],
                        "split": item["split"],
                        "verb_class": verb_class,
                        "condition": condition,
                        "candidate": candidate,
                        "prefix": prefix,
                        "completion": completion,
                        "completion_tokens": count,
                        "log_probability": score,
                        "critical_word_log_probability": critical_score,
                    }
                    baselines.append(row)
                    record(row)
                    cache[(verb_class, condition, candidate)] = (states, pos, lexical, score)
        prepared[item["id"]] = cache

    def intervene(item, layers, controls, cross):
        cache = prepared[item["id"]]
        for verb_class, conditions in item["prefixes"].items():
            for recipient, donor in (("no_comma", "comma"), ("comma", "no_comma")):
                for candidate, completion in item["continuations"].items():
                    states, pos, lexical, baseline = cache[(verb_class, recipient, candidate)]
                    donor_states, donor_pos, _, _ = cache[(verb_class, donor, candidate)]
                    for layer in layers:
                        target, source = states[layer], donor_states[layer]
                        norm = float(torch.linalg.vector_norm(source - target))
                        patches = []
                        if cross:
                            patches.append(("cross_condition", None, source, {}))
                        if controls:
                            patches.append(("identity", None, target, {}))
                            value, info = matched_state(
                                target, lexical[layer] - target, norm, dtype
                            )
                            patches.append(("lexical", None, value, info))
                            for seed in range(3):
                                label = f"{item['id']}:{verb_class}:{recipient}:{layer}:{seed}"
                                stable = int.from_bytes(
                                    hashlib.sha256(label.encode()).digest()[:8], "big"
                                )
                                rng = np.random.default_rng(stable)
                                direction = torch.from_numpy(
                                    rng.normal(size=target.shape).astype("float32")
                                )
                                value, info = matched_state(target, direction, norm, dtype)
                                patches.append(("random", seed, value, info))
                        for kind, seed, value, info in patches:
                            score = measure.score(
                                conditions[recipient], completion, (layer, pos, value)
                            )
                            row = {
                                "record": "intervention",
                                "family": item["family"],
                                "split": item["split"],
                                "verb_class": verb_class,
                                "recipient": recipient,
                                "donor": donor if kind == "cross_condition" else None,
                                "layer": layer,
                                "position": pos,
                                "donor_position": donor_pos if kind == "cross_condition" else None,
                                "candidate": candidate,
                                "kind": kind,
                                "random_seed": seed,
                                "prefix": conditions[recipient],
                                "completion": completion,
                                "lexical_control_prefix": item["lexical_prefixes"][verb_class][
                                    recipient
                                ],
                                "baseline": baseline,
                                "patched": score,
                                "effect": score - baseline,
                                "actual_l2": float(
                                    torch.linalg.vector_norm(
                                        value.to(dtype).float() - target.to(dtype).float()
                                    )
                                ),
                                **info,
                            }
                            interventions.append(row)
                            record(row)
                            if kind == "identity" and abs(row["effect"]) > 1e-4:
                                raise ValueError(f"Identity check failed: {item['id']} L{layer}")

    try:
        for item in (r for r in items if r["split"] == "development"):
            prepare(item)
            intervene(item, range(num_layers - 1), controls=False, cross=True)
            print(f"Garden development: {item['family']}", flush=True)
        development = _intervention_interactions(interventions)
        selected = select_layer(development, num_layers)
        selection = {
            "layer": selected,
            "criterion": "maximum development mean signed bidirectional factorial interaction",
            "excluded_layers": [num_layers - 1],
            "test_layers_computed": [selected],
            "development_family_interactions": development,
        }
        record({"record": "selection_frozen_before_test", **selection})
        for item in items:
            test = item["split"] == "test"
            if test:
                prepare(item)
            intervene(item, [selected], controls=True, cross=test)
            print(f"Garden selected block {selected}: {item['split']} {item['family']}", flush=True)
    except Exception as error:
        record({"record": "aborted", "error_type": type(error).__name__, "message": str(error)})
        raise
    finally:
        raw.close()

    baseline_interactions = []
    for item in items:
        values = {verb_class: {} for verb_class in ("optional_transitive", "intransitive")}
        for verb_class in values:
            for condition in ("comma", "no_comma"):
                cache = prepared[item["id"]]
                values[verb_class][condition] = (
                    cache[(verb_class, condition, "main")][3]
                    - cache[(verb_class, condition, "object")][3]
                )
        baseline_interactions.append(
            {
                "family": item["family"],
                "split": item["split"],
                "margins": values,
                "value": factorial_interaction(values),
                "critical_word_interaction": factorial_interaction(
                    {
                        verb_class: {
                            condition: next(
                                r["critical_word_log_probability"]
                                for r in baselines
                                if r["family"] == item["family"]
                                and r["verb_class"] == verb_class
                                and r["condition"] == condition
                                and r["candidate"] == "main"
                            )
                            for condition in ("comma", "no_comma")
                        }
                        for verb_class in ("optional_transitive", "intransitive")
                    }
                ),
            }
        )
    interactions = _intervention_interactions(interventions)
    summaries = []
    for split in ("development", "test"):
        subset = [r for r in baseline_interactions if r["split"] == split]
        summaries.append(
            {
                "split": split,
                "kind": "behavioral_interaction",
                **family_interval([(r["family"], r["value"]) for r in subset]),
            }
        )
        summaries.append(
            {
                "split": split,
                "kind": "critical_word_interaction",
                **family_interval([(r["family"], r["critical_word_interaction"]) for r in subset]),
            }
        )
        for kind in ("cross_condition", "identity", "lexical", "random"):
            subset = [
                r
                for r in interactions
                if r["split"] == split and r["layer"] == selected and r["kind"] == kind
            ]
            for direction in ("value", "to_no_comma", "to_comma"):
                summaries.append(
                    {
                        "split": split,
                        "kind": kind,
                        "direction": direction,
                        "layer": selected,
                        **family_interval([(r["family"], r[direction]) for r in subset]),
                    }
                )
        selected_rows = [r for r in interactions if r["split"] == split and r["layer"] == selected]
        for control in ("lexical", "random"):
            for direction in ("value", "to_no_comma", "to_comma"):
                paired = []
                for family in {r["family"] for r in selected_rows}:
                    observed = next(
                        r[direction]
                        for r in selected_rows
                        if r["family"] == family and r["kind"] == "cross_condition"
                    )
                    controls = [
                        r[direction]
                        for r in selected_rows
                        if r["family"] == family and r["kind"] == control
                    ]
                    paired.append((family, float(observed - np.mean(controls))))
                summaries.append(
                    {
                        "split": split,
                        "kind": f"cross_minus_{control}",
                        "direction": direction,
                        "layer": selected,
                        **family_interval(sorted(paired)),
                    }
                )
    norm_errors = [
        abs(r["actual_l2"] / r["requested_l2"] - 1)
        for r in interventions
        if r.get("requested_l2", 0) > 0
    ]
    return {
        "materials": items,
        "selection": selection,
        "baselines": baselines,
        "baseline_interactions": baseline_interactions,
        "interventions": interventions,
        "family_interactions": interactions,
        "summaries": summaries,
        "exclusions": [],
        "numerical_checks": {
            "maximum_identity_error": max(
                abs(r["effect"]) for r in interventions if r["kind"] == "identity"
            ),
            "median_control_relative_norm_error_after_cast": float(np.median(norm_errors)),
            "maximum_control_relative_norm_error_after_cast": max(norm_errors),
        },
        "readout": "summed log probability of complete main versus object-compatible continuations",
        "status": "synthetic exploratory assay; no human linguistic validation",
    }
